/* 5 October 2026: pre-event design research. Scripted sample content; no model or media access. */
(() => {
  'use strict';
  const $ = (s) => document.querySelector(s);
  const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons = {
    camera:'<rect x="3" y="6" width="18" height="14" rx="3"/><circle cx="12" cy="13" r="4"/><path d="m8 6 1-3h6l1 3"/>',
    brief:'<path d="M5 3h14v15H9l-4 3z"/><path d="M9 8h6M9 12h5"/>',
    reel:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 8h18M3 16h18M8 3v5M16 3v5M8 16v5M16 16v5"/>',
    settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
    projects:'<path d="M3 7h7l2 2h9v11H3z"/><path d="M3 7V4h7l2 3"/>',
    voice:'<path d="M4 10v4M8 6v12M12 3v18M16 6v12M20 10v4"/>',
    arrow:'<path d="m9 5 7 7-7 7"/>',
    back:'<path d="m15 5-7 7 7 7"/>',
    play:'<path d="m8 4 12 8-12 8z"/>',
    check:'<path d="m5 12 4 4L19 6"/>'
  };
  const icon = (name) => `<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.arrow}</svg>`;
  const presets = {
    fashion:{label:'Fashion reel',short:'Jacket reveal',brief:'A 20-second streetwear reel. Editorial mood, with the jacket as the hero.',hook:'One jacket. A whole different energy.',shots:[['The hook','Look into the lens. Let the jacket fall into frame.'],['The detail','Bring the cuff close to the lens. Hold for a beat.'],['The walk','Take two slow steps toward the camera.'],['The silhouette','Turn slightly sideways. Look over your shoulder.'],['The hero','Face the light. Hold your final pose.']]},
    story:{label:'Walking story',short:'A small daily story',brief:'A 20-second walking-and-talking story about one small moment from today.',hook:'Here’s one thing I noticed today.',shots:[['Open the story','Face the lens and say your opening line.'],['Set the scene','Show a detail of the place around you.'],['Keep walking','Walk slowly and finish your thought.'],['A little pause','Stop and glance toward the scene.'],['Close the story','Look into the lens and share your last thought.']]},
    product:{label:'Product reveal',short:'A considered reveal',brief:'A 20-second product reveal. Clean, quiet, and focused on one useful detail.',hook:'The little detail that makes this different.',shots:[['First glimpse','Hold the product just outside the frame, then reveal it.'],['The detail','Bring one feature close to the lens.'],['In use','Show the product in use with one slow movement.'],['Another angle','Turn the product to show its profile.'],['The finish','Place the product in frame and hold.']]},
    intro:{label:'Introduction',short:'Meet the creator',brief:'A 20-second introduction. Warm and direct, with one thing I love making.',hook:'Hi, I’m here to make something a little different.',shots:[['Say hello','Look at the lens and say your name.'],['Your world','Show something you enjoy making.'],['Your reason','Explain why you care about it.'],['The process','Show one simple part of how you work.'],['An invitation','Look into the lens and invite people to follow along.']]}
  };

  const views = [
    ['camera','Shoot','An idea, a cue, your next take'],
    ['brief','Today’s brief','The idea and its opening line'],
    ['reference','Reference reel','Study a reference, make it yours'],
    ['plan','The shot plan','Poses, timing, and camera roles'],
    ['direction','Live direction','Automatic takes, with a stop button'],
    ['review','Review a take','Your judgment, your final say'],
    ['reel','Edit your reel','Choose the takes that tell your story'],
    ['subtitles','Words & sound','Make the subtitle draft yours'],
    ['cover','Choose a cover','Your opening impression'],
    ['project','Save your project','Keep the brief, takes, and edits'],
    ['projects','Your projects','Reopen and download your saved films'],
    ['settings','Shoot preferences','Cameras, commentary, and timing']
  ];
  const STORAGE_KEY='mini-film.design.projects.v1';
  let state=fresh(), timer=null, toastTimer=null, generation=0;
  let library=readLibrary();
  function fresh() {
    return {view:'camera',type:'fashion',brief:presets.fashion.brief,hook:presets.fashion.hook,
      mood:'Editorial',length:20,shots:presets.fashion.shots.map(([name,cue],i)=>({id:i+1,name,cue,duration:4,source:'phone'})),
      takes:[],shot:0,count:null,recording:false,seconds:0,session:false,phase:'ready',cue:'Let’s make something worth keeping.',
      voice:false,quiet:false,auto:true,devices:{action4:false,drone:null},coordinate:false,
      messages:[],selected:0,cover:0,music:'None',subtitles:[presets.fashion.hook,'Made for the everyday.'],
      playing:false,projectName:'Jacket reveal — today',projectId:null,dirty:true,savedAt:null,cueLog:[],pickupIds:[],reviewGroup:null,reference:emptyReference(),projectQuery:'',briefChatOpen:false};
  }
  function emptyReference(){return {url:'',file:null,shots:[],options:{rhythm:true,angles:true,poses:true},applied:false,provenance:'No analysis performed'};}
  function readLibrary(){try{const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');return Array.isArray(raw)?raw.filter(p=>p&&p.version===1&&typeof p.id==='string'&&p.data&&Array.isArray(p.data.shots)&&p.data.shots.length):[];}catch{return [];}}
  function dirty(){state.dirty=true;}
  function total(){return state.shots.reduce((n,s)=>n+s.duration,0);}
  function editDuration(){return state.takes.reduce((n,t)=>n+t.out-t.in,0);}
  function currentShot(){return state.shots[state.shot%state.shots.length];}
  function sourceName(id){return {phone:'Phone',action4:'Action 4',drone:'Drone pickup'}[id]||'Phone';}
  function sourcesFor(s){if(s.source==='drone')return [];if(state.coordinate&&state.devices.action4)return ['phone','action4'];if(s.source==='action4'&&state.devices.action4)return ['action4'];return ['phone'];}
  function sourceLabel(s){return s.source==='drone'?'Drone · separate pickup':sourcesFor(s).map(sourceName).join(' + ');}
  function logCue(text){state.cue=text;state.cueLog.push({text,phase:state.phase,shotId:currentShot().id,at:new Date().toISOString()});state.cueLog=state.cueLog.slice(-80);}
  function cancel(){generation++;clearTimeout(timer);timer=null;state.count=null;state.recording=false;state.session=false;state.playing=false;if('speechSynthesis'in window)speechSynthesis.cancel();}
  function go(view){cancel();if(state.phase!=='ready'&&state.phase!=='complete')state.phase='paused';state.view=view==='export'?'project':view;location.hash=state.view;render();}
  function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);}
  function speak(text,{duringTake=false,test=false}={}){
    if((!state.voice&&!test)||(state.quiet&&duringTake))return;
    if(!('speechSynthesis'in window)){toast('Voice unavailable here. Live text direction still works.');return;}
    speechSynthesis.cancel();const cue=new SpeechSynthesisUtterance(text);cue.rate=1;
    cue.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('Browser voice could not play. Check your browser audio; text cues remain visible.');};
    speechSynthesis.speak(cue);
  }
  function commentary(on){state.voice=on;if(!on&&'speechSynthesis'in window)speechSynthesis.cancel();render();if(on){speak(state.session?state.cue:'Let’s shoot your idea. '+currentShot().cue,{duringTake:state.recording});toast('Commentary started. Camera timing is controlled separately.');}else toast('Commentary stopped. Capture timing is unchanged.');}
  function header(kicker,title,right=''){return `<header class="view-header"><div><p class="kicker">${kicker}</p><h2>${title}</h2></div>${right}</header>`;}
  function primary(label,action,attrs=''){return `<button class="primary-button" data-action="${action}" ${attrs}>${label}${icon('arrow')}</button>`;}
  function objective(){const idea=state.brief.trim()||presets[state.type].short;return `<button class="objective-pill" data-view="brief" aria-label="Edit your idea"><span><small>YOUR IDEA</small><strong>${esc(idea.length>48?idea.slice(0,45)+'…':idea)} <span>· ${state.length}s</span></strong></span>${icon('arrow')}</button>`;}
  function figure(extra='') { return `<svg class="figure-art ${extra}" viewBox="0 0 340 370" role="img" aria-label="Illustrated fashion framing placeholder, not a camera feed"><defs><linearGradient id="scene-${extra || 'base'}" x2="1" y2="1"><stop stop-color="#bab5a9"/><stop offset="1" stop-color="#777a70"/></linearGradient></defs><rect width="340" height="370" fill="url(#scene-${extra || 'base'})"/><path d="M245 0v370M275 0v370" stroke="#d0cdc2" stroke-width="1" opacity=".35"/><path d="M0 290 340 262v108H0z" fill="#787c71"/><ellipse cx="172" cy="354" rx="60" ry="9" fill="#565c52" opacity=".45"/><path d="m150 232-10 118h30l9-100 8 100h30l-20-118" fill="#30362f"/><path d="m151 94-31 13-16 102 25 4 16-69-7 95h67l-8-95 20 69 24-8-27-99-29-12" fill="#e1ddd2"/><path d="m151 94 26 35 17-34M177 129v110" stroke="#777b70" stroke-width="2"/><path d="m151 95 4-15h30l8 15-16 34z" fill="#b69b84"/><ellipse cx="171" cy="58" rx="25" ry="32" fill="#bda18a"/><path d="M146 59c-8-47 57-48 50 3l-12-28-35 10z" fill="#363b33"/><path d="m158 61 4 1M179 61l4-1" stroke="#5e5146" stroke-width="2"/><path d="m171 62-2 10h5M164 79q8 4 15-1" stroke="#806856" fill="none"/><path d="m105 207-2 23q9 11 19-1l7-16M217 210l7 22q10 7 16-4l-1-24" fill="#bda18a"/><path d="m137 351-5 12h41v-12M187 351v12h40l-10-12" fill="#e5e1d8"/><path d="M158 141h-12v22h12M187 141h12v22h-12" stroke="#acae9f" fill="none"/></svg>`; }
  function camera(){
    const shot=currentShot(),live=state.session;
    const cue=live||state.phase==='paused'?state.cue:shot.cue;
    return `<section class="view camera-view">${header('ONE SHOT AT A TIME','Your shoot',`<button class="icon-button" data-view="settings" aria-label="Shoot preferences">${icon('settings')}</button>`)}${objective()}${live?`<div class="session-strip"><span>${state.recording?'Recording sample take':state.count!==null?'Get ready':'Director running'}</span><button class="small-button session-stop" data-action="stop-shoot">Stop shoot</button></div>`:''}<div class="camera-preview">${figure('camera')}<div class="camera-grid"></div><div class="camera-topbar"><span class="preview-label">${state.recording?'● SAMPLE TAKE':'SAMPLE PREVIEW'}</span></div>${state.devices.action4||state.devices.drone?`<div class="source-strip">${sourcesFor(shot).map(a=>`<span class="source-badge ${state.recording?'active':''}">${sourceName(a)}</span>`).join('')}${state.devices.drone?'<span class="source-badge pending">Drone pickup</span>':''}</div>`:''}<div class="frame-corner tl"></div><div class="frame-corner br"></div>${state.count!==null?`<div class="countdown" aria-live="assertive">${state.count}</div>`:''}${state.recording?`<div class="record-time">00:${String(state.seconds).padStart(2,'0')} / ${shot.duration}s</div>`:''}</div><div class="director-card"><div class="director-meta"><span>SHOT ${state.shot+1} OF ${state.shots.length}</span><button class="voice-guidance-toggle" data-action="${state.voice?'commentary-stop':'commentary-start'}" aria-pressed="${state.voice}" aria-label="${state.voice?'Turn voice guidance off':'Turn voice guidance on'}">${icon('voice')} Voice ${state.voice?'on':'off'}</button></div><h3 class="cue-title" aria-live="polite">${esc(cue)}</h3>${state.recording&&state.quiet?'<small>Voice paused during this take.</small>':''}</div><div class="simple-camera-controls">${primary(live?'Stop shoot':'Start shoot',live?'stop-shoot':'start-director')}<div class="shoot-secondary-links"><button class="text-link" data-view="plan">Edit shot plan</button>${state.takes.length?`<button class="text-link" data-view="reel">Review ${state.takes.length} take${state.takes.length===1?'':'s'} →</button>`:''}</div></div></section>`;
  }

  function brief() {
    return `<section class="view brief-view">${header('ONE IDEA. A FEW GOOD SHOTS.','What are we making?',`<button class="icon-button" data-view="camera" aria-label="Return to shoot">${icon('back')}</button>`)}<div class="scroll-content"><p class="brief-promise">Set your idea. We’ll guide the shots, one at a time.</p><form class="brief-form" id="brief-form"><label>Your idea<textarea name="brief" rows="3" required>${esc(state.brief)}</textarea></label><label>Film length<select name="length">${[...new Set([15,20,30,state.length])].sort((a,b)=>a-b).map(v=>`<option ${state.length===v?'selected':''} value="${v}">${v} seconds</option>`).join('')}</select></label><details class="optional-tools"><summary>Opening line & mood</summary><label>Mood<select name="mood">${['Editorial','Playful','Warm','Clean'].map(v=>`<option ${state.mood===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Your opening line<input name="hook" value="${esc(state.hook)}" maxlength="160"></label></details><button class="secondary-button" type="submit">Update idea</button></form><details class="optional-tools"><summary>Need a starting point?</summary><div class="starter-grid">${Object.entries(presets).map(([id,p],i)=>`<button class="starter-card ${state.type===id?'selected':''}" data-action="preset" data-type="${id}"><span>0${i+1}</span>${p.label}</button>`).join('')}</div><button class="reference-entry" data-view="reference"><span>↗</span><div><strong>Use a reference reel</strong><small>Study its rhythm, angles, and poses.</small></div>${icon('arrow')}</button><p class="demo-note">Starter templates replace the planned shots and current sample takes. Save your project first to keep this version.</p></details><details class="optional-tools" ${state.briefChatOpen?'open':''}><summary>Talk through the idea</summary><div class="message director"><span class="avatar">m.</span><div class="message-body">Tell me one detail you want in your film.<small>Scripted chat example.</small></div></div>${state.messages.map(m=>`<div class="message ${m.role}">${m.role==='director'?'<span class="avatar">m.</span>':''}<div class="message-body">${esc(m.text)}</div></div>`).join('')}<form class="composer" id="chat-form"><input class="composer-input" name="message" placeholder="Add a detail…" aria-label="Message the director" required><button class="composer-send" type="submit" aria-label="Send demo message">↑</button></form></details></div><div class="sticky-action">${primary('Review the shot plan','plan')}</div></section>`;
  }

  // Source bookmarks and synthetic observations are distinct; no media bytes are read.
  function referenceView(){
    const r=state.reference, reviewed=r.shots.filter(s=>s.reviewed).length;
    let elapsed=0;
    const cards=r.shots.map((s,i)=>{
      const start=elapsed;elapsed+=s.duration;
      return `<article class="reference-shot"><div class="reference-shot-heading"><div class="reference-thumbnail" aria-hidden="true">${String(i+1).padStart(2,'0')}</div><div><small>${start}s–${elapsed}s · SAMPLE</small><h3>${esc(s.name)}</h3></div><button class="small-button" data-action="edit-reference-shot" data-index="${i}" aria-label="Edit reference shot ${i+1}">Edit</button></div><div class="reference-shot-tags"><span>${esc(s.framing)}</span><span>${esc(s.angle)}</span><span>${esc(s.movement)}</span></div><p class="reference-details">${esc(s.pose)}</p><small>Transition: ${esc(s.transition)} · creator review required</small><label class="reference-review"><input type="checkbox" data-reference-review="${i}" ${s.reviewed?'checked':''}> I reviewed this shot</label><div class="clip-tools"><button class="text-link" data-action="split-reference-shot" data-index="${i}" ${s.duration<2||r.shots.length>=12?'disabled':''}>Split in two</button>${i<r.shots.length-1?`<button class="text-link" data-action="merge-reference-shot" data-index="${i}" ${s.duration+r.shots[i+1].duration>30?'disabled':''}>Merge with next</button>`:''}</div></article>`;
    }).join('');
    return `<section class="view reference-view">${header('A LITTLE INSPIRATION','Reference reel',`<button class="icon-button" data-view="brief" aria-label="Return to brief">${icon('back')}</button>`)}<div class="scroll-content"><div class="reference-intro"><h3>Like the way it’s shot?</h3><p>Bring the rhythm and angles into your own story.</p></div><div class="reference-stepper"><span>01 · Source</span><span>02 · Shots</span><span>03 · Your version</span></div><form id="reference-link-form" class="brief-form reference-import"><label>Instagram reel link<input name="url" type="url" maxlength="500" placeholder="https://www.instagram.com/reel/…" value="${esc(r.url)}" required></label><button type="submit" class="secondary-button">Save reference link</button><p class="demo-note">A link is a bookmark. It doesn’t grant access to the video. This prototype doesn’t fetch Instagram.</p></form>${r.url?`<div class="reference-status"><strong>Link saved · video needed</strong><p>${esc(r.url)}</p><small>Provide an accessible video for future analysis.</small></div>`:''}<label class="reference-file-label">Choose a video from your device<input id="reference-file" type="file" accept="video/*"></label>${r.file?`<div class="reference-status"><strong>${esc(r.file.name)}</strong><p>${(r.file.size/1048576).toFixed(2)} MB · metadata only</p><small>No video read, uploaded, or analyzed. Re-select the file in a future implementation.</small></div>`:'<p class="demo-note">Use your own video or one you have permission to analyze. Selecting it here stores only its name and size.</p>'}<div class="reference-sample"><p class="kicker">TRY THE DESIGN</p><h3>A jacket reveal in five shots.</h3><p>Explore an invented example, independent of your link or file.</p><button class="secondary-button" data-action="load-reference-sample">${r.shots.length?'Reset sample breakdown':'Explore sample breakdown'}</button></div><p class="demo-note">Trend discovery is a future research item. No trending feed or Instagram connection is running.</p>${r.shots.length?`<div class="section-heading"><h3>The shot breakdown</h3><span>${reviewed}/${r.shots.length} reviewed</span></div><div class="reference-summary">SYNTHETIC SAMPLE · ${elapsed}s<br><small>These observations are invented, not generated from your source.</small></div><div class="reference-list">${cards}</div><div class="reference-options"><h3>What would you like to borrow?</h3>${[['rhythm','Shot rhythm & duration'],['angles','Framing & camera angles'],['poses','Movement & posing']].map(([id,label])=>`<label><input type="checkbox" data-reference-option="${id}" ${r.options[id]?'checked':''}>${label}</label>`).join('')}<p>Keep your objective and opening line. Your new footage tells your story.</p></div>${r.applied?'<p class="reference-status">Sample study applied. Later edits need to be applied again.</p>':''}`:''}</div><div class="sticky-action"><button class="primary-button" data-action="apply-reference" ${!r.shots.length||reviewed!==r.shots.length||!Object.values(r.options).some(Boolean)?'disabled':''}>Use as my shot plan ${icon('arrow')}</button><small class="demo-note">${r.shots.length?reviewed===r.shots.length?'Adaptation is a scripted design example.':'Review every sample shot to continue.':'Explore the sample to try the review flow.'}</small><a class="text-link" href="reference-demo.html" target="_blank" rel="noopener">See what happens next →</a></div></section>`;
  }
  function referenceSample(){return [
    {name:'Opening look',duration:3,framing:'Medium',angle:'Eye level',movement:'Static',pose:'Face the lens. Bring the jacket into frame.',transition:'Hard cut'},
    {name:'Texture detail',duration:3,framing:'Close-up',angle:'Eye level',movement:'Static',pose:'Show the cuff texture, then hold still.',transition:'Match cut'},
    {name:'The walk',duration:5,framing:'Full body',angle:'Low angle',movement:'Subject approaches',pose:'Take two slow steps. Keep your shoulders relaxed.',transition:'Hard cut'},
    {name:'A different side',duration:4,framing:'Medium',angle:'Side view',movement:'Subject turn',pose:'Turn sideways and glance over your shoulder.',transition:'Hard cut'},
    {name:'The final pose',duration:5,framing:'Full body',angle:'Eye level',movement:'Static',pose:'Face the light. Hold your final look.',transition:'Hold to end'}
  ].map(s=>({...s,reviewed:false}));}
  function editReferenceShot(i){const s=state.reference.shots[i];modal('Review this sample shot',`<form id="reference-shot-form" class="brief-form" data-index="${i}"><label>Shot name<input name="name" value="${esc(s.name)}" required maxlength="60"></label><div class="form-row"><label>Duration (seconds)<input name="duration" type="number" min="1" max="30" step="1" value="${s.duration}" required></label><label>Framing<select name="framing">${['Close-up','Medium','Full body','Wide','Unknown'].map(v=>`<option ${s.framing===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Angle<select name="angle">${['Eye level','Low angle','High angle','Side view','Unknown'].map(v=>`<option ${s.angle===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Movement<input name="movement" value="${esc(s.movement)}" required maxlength="100"></label><label>Pose / action<textarea name="pose" required maxlength="250" rows="3">${esc(s.pose)}</textarea></label><label>Transition<input name="transition" value="${esc(s.transition)}" required maxlength="80"></label><p class="demo-note">Edited observations require review again. Angles are descriptive; no focal length or physical camera position is inferred.</p><button class="primary-button" type="submit">Save observation</button></form>`);}
  function applyReference(){
    const r=state.reference;if(!r.shots.length||r.shots.some(s=>!s.reviewed)||!Object.values(r.options).some(Boolean))return;
    cancel();const seed=Math.max(0,...state.shots.map(s=>Number(s.id)||0),...state.takes.map(t=>Number(t.shotId)||0))+1;
    state.shots=r.shots.map((s,i)=>({id:seed+i,name:s.name,duration:r.options.rhythm?s.duration:4,source:'phone',cue:[r.options.angles?`${s.framing}. ${s.angle}.`:'Keep a comfortable phone framing.',r.options.poses?`${s.movement}. ${s.pose}`:'Perform one moment from your objective.',i===0?`Make the opening yours: ${state.hook}`:''].filter(Boolean).join(' '),referenceObservation:{framing:s.framing,angle:s.angle,movement:s.movement,transition:s.transition,provenance:'synthetic sample; creator reviewed'}}));
    state.length=total();state.shot=0;state.phase='ready';r.applied=true;r.provenance='Synthetic sample reviewed and adapted by creator';dirty();go('plan');toast('Sample study adapted. Your objective, opening line, and existing takes are preserved.');
  }

  function shotRows(){return state.shots.map((s,i)=>`<div class="shot-row"><span class="shot-index">0${i+1}</span><div class="shot-info"><strong>${esc(s.name)}</strong><p>${esc(s.cue)}</p><small class="shot-source">${s.source==='phone'&&!state.coordinate?'':esc(sourceLabel(s))+' · '}${s.duration}s</small>${state.takes.some(t=>t.shotId===s.id)?'<span class="clip-status">Draft captured</span>':''}</div><div class="shot-actions"><button class="small-button" data-action="edit-shot" data-index="${i}" aria-label="Edit shot ${i+1}">Edit</button>${i>0?`<button class="small-button" data-action="shot-up" data-index="${i}" aria-label="Move shot ${i+1} up">↑</button>`:''}</div></div>`).join('');}
  function plan(){return `<section class="view">${header('READY WHEN YOU ARE','Your shot plan',`<button class="icon-button" data-view="brief" aria-label="Edit objective">${icon('brief')}</button>`)}<div class="scroll-content"><div class="plan-summary"><p class="kicker">THE HOOK</p><h3>“${esc(state.hook)}”</h3><p>${esc(state.mood)} · ${state.length}s target · ${total()}s planned</p></div><div class="section-heading"><h3>One story, a few good angles.</h3></div><div class="shot-list">${shotRows()}</div><details class="optional-tools"><summary>Camera options</summary><button class="secondary-button" data-view="settings">Set up extra cameras</button><div class="coordination-note">${state.devices.action4?state.coordinate?'Phone + Action 4 run together in this simulation. Choose an angle for each cut afterward.':'Assign each shot to Phone or Action 4; takes run in sequence.':'Start phone-only, or add another camera in preferences.'}${state.devices.drone?' Drone shots stay separate pickups for pilot capture/import.':''}</div></details><p class="demo-note">Editable starter cues. Capture is scripted; real hardware coordination remains untested.</p></div><div class="sticky-action">${primary('Start this shoot','start-director')}</div></section>`;}
  function review(){const t=state.takes[state.selected],s=t||currentShot();return `<section class="view">${header('KEEP THE GOOD PARTS','How did that feel?')}<div class="scroll-content"><div class="take-preview">${figure('review')}<span class="take-badge">SAMPLE TAKE · ${s.duration}s</span><span class="subtitle-overlay">${esc(s.name)}</span></div><div class="review-summary"><p class="kicker">${t?sourceName(t.source)+' · UNREVIEWED DRAFT':'SAMPLE SHOT'}</p><h3>${esc(s.name)}</h3><p>${esc(s.cue)}</p></div><div class="message director"><span class="avatar">m.</span><div class="message-body">The camera handles timing. You decide what makes the cut.<small>Review the take, add a note, or try it again.</small></div></div><label class="review-note">A note for the edit<input id="take-note" value="${esc(t?.note||'')}" placeholder="e.g. Use the last two seconds"></label></div><div class="sticky-action review-actions"><button class="secondary-button" data-action="retake">Try again</button>${primary('Keep take','keep')}</div></section>`;}
  function reelPreview(){const t=state.takes[state.selected];return `<div class="reel-preview">${figure('reel')}<button class="play-button" data-action="play" aria-label="${state.playing?'Pause storyboard preview':'Play storyboard preview'}">${state.playing?'Ⅱ':icon('play')}</button><span class="subtitle-overlay">${esc(state.subtitles[0]||state.hook)}</span><span class="preview-label">${t?sourceName(t.source)+' · ':''}STORYBOARD</span></div>`;}
  function timeline(){return `<div class="timeline">${state.takes.map((t,i)=>`<button class="timeline-clip ${i===state.selected?'selected':''}" data-action="select-clip" data-index="${i}"><span>0${i+1}</span><strong>${esc(t.name)}</strong><small>${t.out-t.in}s</small></button>`).join('')}</div>`;}
  function reel(){
    const back=`<button class="icon-button" data-view="camera" aria-label="Return to shoot">${icon('back')}</button>`;
    if(!state.takes.length)return `<section class="view">${header('MAKE IT YOURS','Your reel',back)}<div class="empty-state">${icon('reel')}<h3>Get your first shot.</h3><p>Your takes will appear here, ready to review and arrange.</p>${primary('Go to shoot','camera')}<details class="optional-tools"><summary>Explore a sample edit</summary><button class="secondary-button" data-action="sample-reel">Load sample reel</button></details><button class="text-link" data-view="project">Save the idea for later →</button></div></section>`;
    const t=state.takes[state.selected]||state.takes[0];
    return `<section class="view reel-view">${header('MAKE IT YOURS','Your reel',back)}<div class="scroll-content">${reelPreview()}<div class="timeline-label"><span>${state.takes.filter(t=>t.reviewed).length} of ${state.takes.length} takes reviewed</span><span>${editDuration()}s</span></div>${timeline()}<div class="edit-panel"><div class="editor-summary"><strong>${esc(t.name)}</strong><span class="clip-status ${t.reviewed?'reviewed':''}">${t.reviewed?'Reviewed':'Review this take'}</span></div><button class="secondary-button" data-action="review-clip">${t.reviewed?'Review again':'Review take'}</button><details class="edit-tools"><summary>Adjust this clip</summary>${t.angles.length>1?`<label class="source-select">Camera angle<select id="clip-angle">${t.angles.map(a=>`<option value="${a}" ${t.source===a?'selected':''}>${sourceName(a)}</option>`).join('')}</select></label>`:''}<div class="form-row"><label>Start (seconds)<input type="number" min="0" max="${t.duration-1}" value="${t.in}" data-trim="in"></label><label>End (seconds)<input type="number" min="1" max="${t.duration}" value="${t.out}" data-trim="out"></label></div><div class="clip-tools"><button class="secondary-button" data-action="clip-up" ${state.selected===0?'disabled':''}>Move earlier</button><button class="secondary-button" data-action="remove-clip">Remove clip</button></div><p class="demo-note">${esc(t.note||'Illustrated sample take. Your changes stay editable.')}</p></details></div><details class="finishing-tools"><summary>Captions, sound & cover</summary><button class="secondary-button" data-view="subtitles">Edit captions & sound</button><button class="secondary-button" data-view="cover">Choose a cover</button></details>${state.pickupIds.length?`<p class="demo-note">${state.pickupIds.length} drone pickup${state.pickupIds.length===1?'':'s'} still need separate capture/import.</p>`:''}</div><div class="sticky-action">${primary('Save project','project')}</div></section>`;
  }

  function subtitles() {return `<section class="view">${header('MAKE IT SOUND LIKE YOU','Words & sound',`<button class="icon-button" data-view="reel" aria-label="Return to reel">${icon('back')}</button>`)}<div class="scroll-content">${reelPreview()}<p class="section-label">SUBTITLE DRAFT · REVIEW EVERY LINE</p>${state.subtitles.map((s,i)=>`<label class="subtitle-row"><span>0${i+1} <small>${i*4}s–${i*4+4}s</small></span><textarea rows="2" data-subtitle="${i}">${esc(s)}</textarea></label>`).join('')}<label class="music-label">Music direction<select id="music">${['None','Minimal beat','Soft ambient','Original voice only'].map(s=>`<option ${state.music===s?'selected':''}>${s}</option>`).join('')}</select></label><p class="demo-note">Sample subtitles, not transcription. Music is an edit note; no audio track is included.</p></div><div class="sticky-action">${primary('Apply & return to reel','reel')}</div></section>`;}
  function cover() {return `<section class="view">${header('THE FIRST IMPRESSION','Choose a cover',`<button class="icon-button" data-view="reel" aria-label="Return to reel">${icon('back')}</button>`)}<div class="scroll-content"><div class="take-preview cover-preview">${figure('cover')}<span class="subtitle-overlay">${esc(['A different energy.','Details make the outfit.','Made for the everyday.'][state.cover])}</span></div><p class="section-label">A FRAME FROM YOUR STORY</p><div class="cover-choices">${['The hook','The detail','The hero'].map((s,i)=>`<button class="cover-choice ${state.cover===i?'selected':''}" data-action="cover" data-index="${i}"><span>0${i+1}</span>${s}</button>`).join('')}</div><p class="demo-note">Illustrated placeholders. Cover selection is saved in the project.</p></div><div class="sticky-action">${primary('Use this cover','reel')}</div></section>`;}
  function projectData(){return {type:state.type,brief:state.brief,hook:state.hook,mood:state.mood,length:state.length,shots:state.shots,takes:state.takes,messages:state.messages,subtitles:state.subtitles,music:state.music,cover:state.cover,devices:state.devices,coordinate:state.coordinate,quiet:state.quiet,auto:state.auto,pickupIds:state.pickupIds,reference:state.reference};}
  function saveProject(){
    const project={version:1,kind:'mini-film-design-project',id:state.projectId||'project-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),name:state.projectName.trim()||'Untitled film',updatedAt:new Date().toISOString(),provenance:'5 October 2026 pre-event design; synthetic media and hardware states.',data:JSON.parse(JSON.stringify(projectData()))};
    const next=[project,...library.filter(p=>p.id!==project.id)];
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));library=next;state.projectId=project.id;state.projectName=project.name;state.savedAt=project.updatedAt;state.dirty=false;render();toast('Project saved in this browser. You can reopen it after a refresh.');}catch{toast('Browser storage is unavailable or full. Download the project JSON to keep your work.');}
  }
  function loadProject(id){const p=library.find(p=>p.id===id);if(!p)return;cancel();const s=fresh();Object.assign(s,JSON.parse(JSON.stringify(p.data)));s.projectName=p.name;s.projectId=p.id;s.savedAt=p.updatedAt;s.dirty=false;s.view='project';s.voice=false;s.session=false;s.recording=false;s.count=null;s.playing=false;s.phase='ready';s.shot=0;s.selected=0;s.cue='Project reopened. Start the director when you are ready.';state=s;location.hash='project';render();toast('Project reopened. Cameras and commentary are stopped.');}
  function projectView(){return `<section class="view project-view">${header('KEEP CREATING, COME BACK LATER','Your project',`<button class="icon-button" data-view="reel" aria-label="Return to reel">${icon('back')}</button>`)}<div class="scroll-content"><div class="project-hero"><span class="project-icon">${icon('reel')}</span><label>PROJECT NAME<input class="project-name-input" id="project-name" value="${esc(state.projectName)}" maxlength="100"></label><div class="project-meta"><span>${state.shots.length} planned shots</span><span>${state.takes.length} drafts</span><span>${editDuration()}s cut</span></div><p class="save-status" id="save-status">${state.dirty?'● Unsaved changes':`✓ Saved ${new Date(state.savedAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`}</p></div><details class="optional-tools"><summary>What’s included?</summary><div class="project-checklist"><div><span>Brief & shot plan</span><strong>Editable</strong></div><div><span>Camera roles</span><strong>${state.devices.action4?'Phone + Action 4':'Phone'}${state.devices.drone?' + drone pickups':''}</strong></div><div><span>Draft review</span><strong>${state.takes.filter(t=>t.reviewed).length} / ${state.takes.length} reviewed</strong></div><div><span>Reference study</span><strong>${state.reference.applied?'Sample plan adapted':state.reference.shots.length?'Sample reviewed in progress':state.reference.url||state.reference.file?'Source noted only':'None yet'}</strong></div><div><span>Subtitles, music, cover</span><strong>Included</strong></div></div></details><div class="project-actions"><button class="secondary-button" data-action="download-project">Download project backup</button></div><p class="demo-note">Saved only in this browser. JSON is a portable backup of the editable design; sample footage is not a video file. Clearing site storage removes saved projects.</p><button class="secondary-button" data-view="projects">View all saved projects →</button><button class="text-link" data-action="another">Start another film →</button></div><div class="sticky-action">${primary(state.dirty?'Save project':'Save project again','save-project')}</div></section>`;}

  function projectStage(project){const takes=Array.isArray(project.data.takes)?project.data.takes:[];return !takes.length?'Planned':takes.every(t=>t.reviewed)?'Reviewed edit':'In progress';}
  function libraryCards(){const query=state.projectQuery.trim().toLowerCase(),items=library.filter(p=>p.name.toLowerCase().includes(query));return items.length?items.map((p,i)=>`<article class="library-project"><div class="library-project-art" aria-hidden="true">${String(i+1).padStart(2,'0')}</div><div class="library-project-info"><strong>${esc(p.name)}</strong><small>${new Date(p.updatedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · ${p.data.shots.length} shots · ${(p.data.takes||[]).length} takes</small><span class="project-stage ${projectStage(p)==='Reviewed edit'?'reviewed':'draft'}">${projectStage(p)}${p.id===state.projectId?' · Current':''}</span></div><div class="library-project-actions"><button class="secondary-button" data-action="open-project" data-id="${esc(p.id)}" aria-label="Open ${esc(p.name)}">Open</button><button class="secondary-button" data-action="download-saved-project" data-id="${esc(p.id)}" aria-label="Download ${esc(p.name)}">Download ↓</button></div></article>`).join(''):`<div class="library-empty"><h3>${query?'No matching projects.':'Your films live here.'}</h3><p>${query?'Try another project name.':'Save a project to return to its idea, takes, and edit whenever you want.'}</p>${query?'':primary('Continue your first film','camera')}</div>`;}
  function projectsView(){return `<section class="view projects-view">${header('KEEP EVERY STORY','Your projects',`<button class="small-button" data-action="another">New film +</button>`)}<div class="scroll-content"><details class="library-draft draft-disclosure" ${library.length?'':'open'}><summary>Current film${state.dirty?' · unsaved':''}</summary><p class="kicker">${state.dirty?'CURRENT DRAFT · UNSAVED CHANGES':'CURRENT FILM'}</p><h3>${esc(state.projectName)}</h3><p>${state.takes.length?`${state.takes.length} takes ready to shape.`:'Your idea and shot plan are ready.'}</p><div class="library-project-actions"><button class="secondary-button" data-view="${state.takes.length?'reel':'camera'}">Continue</button><button class="secondary-button" data-view="project">${state.dirty?'Save draft':'Project details'}</button></div></details><div class="section-heading"><h3>Saved films</h3><span class="library-summary">${library.length} saved</span></div>${library.length?`<label class="project-search-label">Find a project<input id="project-search" type="search" value="${esc(state.projectQuery)}" placeholder="Search by name…"></label>`:''}<div id="saved-project-list">${libraryCards()}</div><div class="library-toolbar"><button class="secondary-button" data-action="download-project-library" ${library.length?'':'disabled'}>Download all project backups</button></div><p class="demo-note">Saved on this browser. Downloads are editable project backups (JSON); this wireframe doesn’t include video files. Clearing site storage removes the library. Download backups to keep a separate copy.</p></div></section>`;}

  function deviceCard(id,title,detail,status,action,label){return `<article class="device-card"><div class="device-heading"><span class="device-icon">${icon('camera')}</span><div class="device-copy"><strong>${title}</strong><p>${detail}</p></div><span class="device-status ${status==='In plan'?'added':'research'}">${status}</span></div>${action?`<div class="device-actions"><button class="secondary-button" data-action="${action}">${label}</button></div>`:''}</article>`;}
  function settings(){
    const toggle=(label,description,on,action)=>`<div class="setting-row"><div><strong>${label}</strong><p>${description}</p></div><button class="toggle ${on?'on':''}" role="switch" aria-checked="${on}" data-action="${action}" aria-label="${label}"></button></div>`;
    return `<section class="view settings-view">${header('KEEP IT COMFORTABLE','Shoot settings',`<button class="icon-button" data-view="camera" aria-label="Return to shoot">${icon('back')}</button>`)}<div class="scroll-content"><div class="settings-section"><h3>Voice guidance</h3>${toggle('Speak the directions','Hear the next pose, Action and Cut.',state.voice,'voice')}${toggle('Quiet during takes','Keep directions out of your spoken dialogue.',state.quiet,'quiet')}<p class="demo-note">Optional browser voice in this prototype.</p></div><details class="optional-tools"><summary>Extra cameras</summary><div class="camera-roster">${deviceCard('phone','Phone','Your main camera','In plan')}${deviceCard('action4','DJI Action 4',state.devices.action4?'Side angle · setup concept':'Add an optional side angle',state.devices.action4?'In plan':'Optional',state.devices.action4?'remove-action4':'add-action4',state.devices.action4?'Remove from plan':'Add sample Action 4')}${deviceCard('drone','Drone',state.devices.drone?state.devices.drone==='neo2'?'DJI Fly · manual capture/import':'Mini 4 Pro · read-only probe research':'A separately captured wide shot',state.devices.drone?'In plan':'Optional',state.devices.drone?'drone-options':'add-drone',state.devices.drone?'Drone options':'Plan a drone pickup')}</div>${state.devices.action4?toggle('Capture together','Phone + Action 4 sample angles, one editable cut.',state.coordinate,'coordinate'):''}<p class="demo-note">Planning only. No Bluetooth scan, connection, recording or flight command occurs.</p></details><details class="optional-tools"><summary>Timing & voice test</summary>${toggle('Automatic shot sequence','Finish one take, then move to the next.',state.auto,'auto-sequence')}<button class="secondary-button" data-action="test-voice">Test browser voice</button><button class="text-link" data-action="cue-log">View past director cues →</button><p class="demo-note">Earbud playback remains unverified. Drone capture is separate.</p></details></div></section>`;
  }

  const notes={
    camera:['Start the director, keep control.','The shot plan handles take timing. Start and stop commentary separately; Stop shoot cancels the whole session.','Idea / one cue / optional voice / Start–Stop','Editable plan → bounded session coordinator'],
    brief:['Start with intent.','A daily idea becomes a hook and an editable plan. The chat is a scripted design conversation.','Scene types / objective / length / mood / hook','Language interpretation → creator-approved brief'],
    reference:['Study the structure. Make it yours.','Save a reference link, then review an explicitly synthetic shot breakdown. Nothing is downloaded or analyzed in this prototype.','Source / editable sample cuts / framing / pose / review / adaptation','Cut detector → sampled-frame VLM + pose/speech → reviewed plan; see reference-reels.md'],
    plan:['Give every camera a role.','Choose Phone, Action 4, or a separate drone pickup per shot. Paired phone/action footage shares one timeline slot in this mock.','Hook / timing / camera assignment / paired angles','Plan + verified camera capabilities → allowed capture schedule'],
    direction:['The director keeps the rhythm.','Preparation, countdown, Action, midpoint cue, and Cut follow a cancellable schedule. These are timed sample cues.','Live commentary / auto takes / Stop / quiet mode','Proposed Kokoro cues + bounded timing; optional Moonshine speech is a separate input'],
    review:['Automatic is still editable.','Automatically collected takes remain drafts until reviewed. Keep, retake, or remove each one.','Draft preview / note / Keep / retake','Clip observations, later → creator review'],
    reel:['One cut, several perspectives.','Review clips, trim their timing, and switch between paired sample angles without doubling the reel length.','Draft status / angle choice / trim / order / words / cover','Reviewed cut list → deterministic media pipeline'],
    subtitles:['Make it sound like you.','The subtitle draft and music direction stay editable and travel with the project.','Subtitle text / music note / current preview','Proposed Moonshine transcription → reviewed timed text; sample captions today'],
    cover:['A deliberate opening.','Choose a frame concept that fits the story. Save it with the cut rather than making export a separate workflow.','Cover choices / preview / project metadata','Candidate frames → creator selection'],
    projects:['Every film, easy to find.','Reopen a saved project or download its exact saved snapshot directly. The current draft stays separate until saved.','Saved films / search / Open / Download / backup all','Existing browser-local library; downloads do not mutate drafts'],
    project:['Save now. Finish later.','Save a named project locally, reopen it after a refresh, or download its JSON. Reopening never resumes capture or voice.','Project name / save status / local library / portable backup','Versioned project storage; video export is secondary'],
    settings:['A small crew, in one place.','Phone first, Action 4 Bluetooth setup concept, and drone pickup planning. No unverified connection appears as real.','Camera roster / pairing concept / drone route / cue timing','Separate camera adapters and acknowledgements; no hardware in this mock']
  };
  function inspector(){const n=notes[state.view]||notes.camera;$('#inspector').innerHTML=`<p class="eyebrow">WHY THIS VIEW EXISTS</p><div class="inspector-card"><span class="component-tag">${String(Math.max(0,views.findIndex(v=>v[0]===state.view))+1).padStart(2,'0')} / EXPERIENCE · V5</span><h2 class="inspector-title">${n[0]}</h2><p>${n[1]}</p></div><div class="inspector-card"><p class="eyebrow">ON THE SURFACE</p><ul class="detail-list">${n[2].split(' / ').map(s=>`<li>${s}</li>`).join('')}</ul></div><div class="inspector-card"><p class="eyebrow">BEHIND THE SCENES · PROPOSED</p><div class="model-row">${n[3]}</div><p class="demo-note">Sample timings and camera states. No model or hardware integration runs here.</p></div><div class="legend"><span class="legend-dot"></span> Coral = your next action<br><span class="legend-dot neutral"></span> Projects save locally in this browser</div><a class="text-link" href="README.md" target="_blank" rel="noopener">Read the design brief ↗</a><br><a class="text-link" href="speech-models.md" target="_blank" rel="noopener">Speech model candidates ↗</a>`;}
  function render(){
    const overview=state.view==='overview';$('#phone-wrapper').hidden=overview;$('#overview-board').hidden=!overview;
    const workshopRoutes=['camera','reel','projects'];
    $('#screen-list').innerHTML=workshopRoutes.map((id,i)=>{const [,name,desc]=views.find(v=>v[0]===id);return `<button class="${state.view===id?'active':''}" data-view="${id}"><span class="screen-number">${String(i+1).padStart(2,'0')}</span><span class="screen-label">${name}<small>${desc}</small></span>${icon('arrow')}</button>`;}).join('')+`<button data-view="settings"><span class="screen-number">${icon('settings')}</span><span class="screen-label">Settings<small>Optional cameras and commentary</small></span></button>`;
    const group=state.view==='projects'?'projects':['reel','review','subtitles','cover','project'].includes(state.view)?'reel':'camera';
    $('#app-nav').innerHTML=[['camera','Shoot'],['reel','Edit'],['projects','Projects']].map(([id,label])=>`<button class="nav-btn ${group===id?'active':''}" data-view="${id}">${icon(id)}<span>${label}</span></button>`).join('');
    if(overview){overviewRender();return;}
    $('#inspector').hidden=false;$('#screen').innerHTML=({camera,direction:camera,brief,reference:referenceView,plan,review,reel,subtitles,cover,project:projectView,projects:projectsView,settings}[state.view]||camera)();$('#stage-caption').textContent=views.find(v=>v[0]===state.view)?.[2]||'Explore the flow.';inspector();
  }
  function overviewRender(){$('#inspector').hidden=true;$('#stage-caption').textContent=`${views.length} views, three destinations. Click a card to explore.`;$('#overview-board').innerHTML=`<div class="overview-title"><p class="eyebrow">MINI FILM / EXPERIENCE MAP · V5</p><h2>Plan it. Shoot it. Make it yours.</h2><p>Three destinations: Shoot → Edit → Projects.</p></div>${views.map(([id,name,desc],i)=>`<button class="overview-card" data-view="${id}"><span class="kicker">${String(i+1).padStart(2,'0')} / ${['camera','direction','review','settings'].includes(id)?'DIRECT':['brief','reference','plan'].includes(id)?'BRIEF':'EDIT'}</span><div class="mini-screen">${['camera','direction','review','reel','cover'].includes(id)?figure('mini-'+id):`<div class="mini-content"><span class="mini-pill"></span><span class="mini-line"></span><span class="mini-line short"></span>${Array.from({length:3},(_,j)=>`<div class="mini-row"><span>0${j+1}</span><i></i></div>`).join('')}</div>`}<span class="mini-action"></span></div><strong>${name}</strong><p>${desc}</p></button>`).join('')}<div class="overview-steps">Shoot → Edit → Projects<span>Pre-event design research · 05 Oct 2026</span></div>`;}
  function modal(title,content){$('#sheet-title').textContent=title;$('#sheet-content').innerHTML=content;$('#sheet').showModal();}
  function schedule(fn,ms,owner=generation){timer=setTimeout(()=>{if(owner===generation&&state.session)fn(owner);},ms);}
  function startDirector(){cancel();state.session=true;state.phase='preparing';state.view='direction';location.hash='direction';state.seconds=0;state.reviewGroup=null;runShot(generation);}
  function runShot(owner){
    const s=currentShot();state.seconds=0;state.recording=false;state.count=null;
    if(s.source==='drone'){state.phase='pickup';if(!state.pickupIds.includes(s.id))state.pickupIds.push(s.id);dirty();logCue(`${s.name}: planned as a separate drone pickup. Continuing with the phone shoot.`);speak('Drone pickup planned.');render();schedule(()=>advance(owner),1400,owner);return;}
    state.phase='preparing';logCue(s.cue);speak(s.cue);render();schedule(()=>countDown(3,owner),1600,owner);
  }
  function countDown(n,owner){state.phase='countdown';state.count=n;logCue(n===3?'Ready. Three, two, one…':state.cue);speak(String(n));render();schedule(()=>n>1?countDown(n-1,owner):beginTake(owner),1000,owner);}
  function beginTake(owner){state.count=null;state.phase='recording';state.recording=true;state.seconds=0;logCue('Action. '+currentShot().cue);speak('Action. '+currentShot().cue,{duringTake:true});render();schedule(()=>takeTick(owner),1000,owner);}
  function takeTick(owner){state.seconds++;const s=currentShot();if(state.seconds>=s.duration){finishAutomatic(owner);return;}if(state.seconds===Math.max(1,Math.floor(s.duration/2))){logCue('Keep it slow. Hold this framing.');speak('Keep it slow. Hold this framing.',{duringTake:true});}render();schedule(()=>takeTick(owner),1000,owner);}
  function collectDraft(duration,note=''){const s=currentShot(),angles=sourcesFor(s);if(!angles.length||duration<=0)return;const t={id:'take-'+Date.now().toString(36)+'-'+state.takes.length,shotId:s.id,name:s.name,cue:s.cue,duration,in:0,out:duration,source:angles[0],angles,reviewed:false,note,sync:angles.length>1?'paired synthetic angles; hardware sync unverified':'single synthetic angle'};state.takes.push(t);state.selected=state.takes.length-1;state.reviewGroup=t.id;dirty();}
  function finishAutomatic(owner){collectDraft(currentShot().duration);state.recording=false;state.phase='between';logCue('Cut. Take saved as a draft.');speak('Cut.');render();schedule(()=>{if(state.auto)advance(owner);else{cancel();state.view='review';location.hash='review';render();}},1500,owner);}
  function advance(owner){if(!state.auto){cancel();state.view=state.takes.length?'review':'plan';location.hash=state.view;render();return;}if(state.shot<state.shots.length-1){state.shot++;runShot(owner);}else{state.phase='complete';logCue('Shoot complete. Let’s review the takes.');cancel();state.phase='complete';state.view='reel';location.hash='reel';render();toast('Shoot finished. Draft takes are ready to review; drone pickups stay separate.');}}
  function stopShoot(){if(state.recording&&state.seconds>0)collectDraft(Math.min(state.seconds,currentShot().duration),'Stopped early; review this partial sample take.');cancel();state.phase='paused';logCue('Shoot stopped. Your draft takes are still here.');render();toast('Shoot stopped. All future take and commentary cues cancelled.');}
  function sampleReel(){state.takes=state.shots.filter(s=>s.source!=='drone').map((s,i)=>({id:'sample-'+i,shotId:s.id,name:s.name,cue:s.cue,duration:s.duration,in:0,out:s.duration,source:sourcesFor(s)[0],angles:sourcesFor(s),reviewed:false,note:'Illustrated sample take. No video source.',sync:'synthetic sample only'}));state.pickupIds=state.shots.filter(s=>s.source==='drone').map(s=>s.id);state.selected=0;dirty();}
  function downloadJson(payload,name,message){const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=(String(name).replace(/[^a-z0-9_-]/gi,'-').slice(0,70)||'mini-film')+'.project.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(message);}
  function downloadProject(){downloadJson({version:1,kind:'mini-film-design-project',id:state.projectId,name:state.projectName,updatedAt:new Date().toISOString(),provenance:'5 October 2026 pre-event design; synthetic media and hardware states.',data:projectData()},state.projectName,'Current project backup downloaded. No video rendered.');}
  function downloadSavedProject(id){const p=library.find(p=>p.id===id);if(p)downloadJson(p,p.name,'Saved project backup downloaded. Your current draft is unchanged.');}
  function downloadLibrary(){if(!library.length)return;downloadJson({version:1,kind:'mini-film-design-library',exportedAt:new Date().toISOString(),provenance:'Pre-event design; saved metadata only, no videos.',projects:library},'mini-film-all-projects','All saved project backups downloaded. Your current draft is unchanged.');}

  function action4Sheet(){modal('Add DJI Action 4',`<p>A side angle, without changing your phone-first flow.</p><div class="discovery-device"><span class="device-icon">${icon('camera')}</span><div><strong>DJI Action 4 · sample camera</strong><p>Bluetooth control setup concept</p></div></div><p class="demo-note">No scan or pairing is performed. Real Android Bluetooth permission, camera confirmation, recording acknowledgement, and source files must be validated separately. Bluetooth control does not imply a video preview.</p>${primary('Add sample Action 4','confirm-action4')}`);}
  function droneSheet(){modal('Add a drone to the plan',`<p>Keep a wide angle in the story. Capture it separately, then review/import the original clip.</p><div class="route-grid"><button class="route-card" data-action="confirm-drone" data-route="neo2"><strong>DJI Neo 2</strong><span>DJI Fly · manual capture / import</span><small>No custom SDK or Bluetooth connection implied.</small></button><button class="route-card" data-action="confirm-drone" data-route="mini4"><strong>DJI Mini 4 Pro</strong><span>Read-only SDK probe research</span><small>Propellers-off preview/telemetry milestone. Capture/control are later gates.</small></button></div><p class="pilot-note">Adding a drone only assigns a pickup to the shot plan. Start director never records, moves, or flies a drone.</p>${state.devices.drone?'<button class="secondary-button" data-action="remove-drone">Remove drone from plan</button>':''}`);}
  document.addEventListener('click',e=>{
    const b=e.target.closest('[data-action],[data-view]');if(!b||b.disabled)return;
    if(b.dataset.view){go(b.dataset.view);return;}
    const a=b.dataset.action,i=Number(b.dataset.index);if(views.some(v=>v[0]===a)&&b.dataset.index===undefined){go(a);return;}
    switch(a){
      case 'load-reference-sample':if(state.reference.shots.length)modal('Reset sample observations?',`<p>This replaces your sample observation edits. Your current shoot plan and takes stay intact.</p><div class="review-actions"><button class="secondary-button" data-action="close-sheet">Keep edits</button><button class="primary-button" data-action="confirm-reference-sample">Reset sample</button></div>`);else{state.reference.shots=referenceSample();state.reference.applied=false;dirty();render();}break;
      case 'confirm-reference-sample':$('#sheet').close();state.reference.shots=referenceSample();state.reference.applied=false;dirty();render();break;
      case 'edit-reference-shot':editReferenceShot(i);break;
      case 'split-reference-shot':{const r=state.reference,s=r.shots[i];if(s.duration<2||r.shots.length>=12)break;const first=Math.floor(s.duration/2);r.shots.splice(i,1,{...s,duration:first,reviewed:false},{...s,name:(s.name+' · part 2').slice(0,60),duration:s.duration-first,reviewed:false});r.applied=false;dirty();render();}break;
      case 'merge-reference-shot':{const r=state.reference,s=r.shots[i],next=r.shots[i+1];if(!next||s.duration+next.duration>30)break;r.shots.splice(i,2,{...s,name:(s.name+' + '+next.name).slice(0,60),duration:s.duration+next.duration,framing:s.framing===next.framing?s.framing:'Unknown',angle:s.angle===next.angle?s.angle:'Unknown',movement:(s.movement+' / '+next.movement).slice(0,100),pose:(s.pose+' '+next.pose).slice(0,250),transition:next.transition,reviewed:false});r.applied=false;dirty();render();}break;
      case 'apply-reference':modal('Use this sample as your plan?',`<p>This replaces the planned shots with your reviewed sample study. Your objective, opening line, and existing takes are preserved. Existing takes keep their original shot identities.</p><p class="demo-note">New shots start on the phone. Assign optional cameras afterward.</p><div class="review-actions"><button class="secondary-button" data-action="close-sheet">Keep current plan</button><button class="primary-button" data-action="confirm-apply-reference">Use reviewed sample</button></div>`);break;
      case 'confirm-apply-reference':$('#sheet').close();applyReference();break;
      case 'overview':go('overview');break;
      case 'reset':cancel();state=fresh();go('camera');toast('Demo reset. Saved projects are still in Your project.');break;
      case 'start-director':startDirector();break;
      case 'stop-shoot':stopShoot();break;
      case 'commentary-start':commentary(true);break;
      case 'commentary-stop':commentary(false);break;
      case 'voice':commentary(!state.voice);break;
      case 'quiet':state.quiet=!state.quiet;dirty();if(state.quiet&&state.recording&&'speechSynthesis'in window)speechSynthesis.cancel();render();break;
      case 'auto-sequence':state.auto=!state.auto;dirty();render();break;
      case 'test-voice':speak('Face the light. Three, two, one. Action.',{test:true});toast('Browser voice sample. Check your selected output.');break;
      case 'cue-log':modal('Director cue history',`<p>Timed sample cues, not observations of your live surroundings.</p><ol class="cue-log">${state.cueLog.length?state.cueLog.map(c=>`<li><strong>${esc(c.phase)}</strong> ${esc(c.text)}</li>`).join(''):'<li>Start the director to see its cue sequence.</li>'}</ol>`);break;
      case 'lens':toast('Phone lens placeholder. No camera connected.');break;
      case 'choose-shot':cancel();state.shot=i;state.phase='ready';go('direction');break;
      case 'preset':cancel();{const p=presets[b.dataset.type];state.type=b.dataset.type;state.brief=p.brief;state.hook=p.hook;state.projectName=p.short+' — today';state.shots=p.shots.map(([name,cue],i)=>({id:i+1,name,cue,duration:state.length/5,source:'phone'}));if(state.devices.drone)state.shots[4].source='drone';state.shot=0;state.takes=[];state.pickupIds=[];state.messages=[];state.subtitles=[p.hook,'Made for the everyday.'];state.phase='ready';dirty();render();}break;
      case 'edit-shot':{const s=state.shots[i];modal('Edit this shot',`<form id="shot-form" class="brief-form" data-index="${i}"><label>Shot name<input name="name" value="${esc(s.name)}" required maxlength="60"></label><label>Spoken cue<textarea name="cue" required rows="3">${esc(s.cue)}</textarea></label><div class="form-row"><label>Duration (seconds)<input name="duration" type="number" min="1" max="30" step="1" value="${s.duration}" required></label><label>Camera role<select name="source"><option value="phone" ${s.source==='phone'?'selected':''}>Phone</option>${state.devices.action4?`<option value="action4" ${s.source==='action4'?'selected':''}>Action 4</option>`:''}${state.devices.drone?`<option value="drone" ${s.source==='drone'?'selected':''}>Drone pickup</option>`:''}</select></label></div><p class="demo-note">Paired Phone + Action 4 applies to non-drone shots when Capture together is enabled. Drone roles are separately captured/imported pickups.</p><button class="primary-button" type="submit">Save shot ${icon('check')}</button></form>`);break;}
      case 'shot-up':[state.shots[i-1],state.shots[i]]=[state.shots[i],state.shots[i-1]];state.shot=0;dirty();render();break;
      case 'close-sheet':$('#sheet').close();break;
      case 'cameras':go('settings');break;
      case 'add-action4':action4Sheet();break;
      case 'confirm-action4':state.devices.action4=true;state.coordinate=true;dirty();$('#sheet').close();render();toast('Sample Action 4 added. Paired angles are enabled in this design.');break;
      case 'remove-action4':state.devices.action4=false;state.coordinate=false;state.shots.forEach(s=>{if(s.source==='action4')s.source='phone';});dirty();render();break;
      case 'coordinate':state.coordinate=!state.coordinate;dirty();render();break;
      case 'add-drone':case 'drone-options':droneSheet();break;
      case 'confirm-drone':state.devices.drone=b.dataset.route;state.shots[state.shots.length-1].source='drone';dirty();$('#sheet').close();render();toast('Drone pickup added to the plan. Capture remains separate.');break;
      case 'remove-drone':state.devices.drone=null;state.shots.forEach(s=>{if(s.source==='drone')s.source='phone';});state.pickupIds=[];dirty();$('#sheet').close();render();break;
      case 'review-clip':go('review');break;
      case 'retake':{const t=state.takes[state.selected];if(t){const n=state.shots.findIndex(s=>s.id===t.shotId);state.shot=n<0?0:n;}go('direction');break;}
      case 'keep':{const t=state.takes[state.selected];if(t){t.reviewed=true;t.note=$('#take-note').value;dirty();go('reel');toast('Take reviewed. Your edit stays editable.');}else{collectDraft(currentShot().duration,$('#take-note').value);state.takes[state.selected].reviewed=true;go('reel');}break;}
      case 'sample-reel':sampleReel();go('reel');break;
      case 'select-clip':state.selected=i;render();break;
      case 'clip-up':if(state.selected>0){const n=state.selected;[state.takes[n-1],state.takes[n]]=[state.takes[n],state.takes[n-1]];state.selected--;}dirty();render();break;
      case 'remove-clip':state.takes.splice(state.selected,1);state.selected=Math.max(0,state.selected-1);dirty();render();break;
      case 'cover':state.cover=i;dirty();render();break;
      case 'save-project':saveProject();break;
      case 'download-project':downloadProject();break;
      case 'download-saved-project':downloadSavedProject(b.dataset.id);break;
      case 'download-project-library':downloadLibrary();break;
      case 'open-project':if(state.dirty)modal('Open a saved project?',`<p>Your current draft has unsaved changes. Save it first if you want to keep them.</p><div class="review-actions"><button class="secondary-button" data-action="close-sheet">Keep editing</button><button class="primary-button" data-action="confirm-open" data-id="${esc(b.dataset.id)}">Open saved project</button></div>`);else loadProject(b.dataset.id);break;
      case 'confirm-open':$('#sheet').close();loadProject(b.dataset.id);break;
      case 'another':modal('Start another film?',`<p>Save your current project first if you want to keep the latest edits. Your saved library will stay here.</p><div class="review-actions"><button class="secondary-button" data-action="close-sheet">Keep editing</button><button class="primary-button" data-action="confirm-another">Start fresh</button></div>`);break;
      case 'confirm-another':$('#sheet').close();cancel();state=fresh();go('brief');break;
      case 'play':if(!state.takes.length)break;if(state.playing){cancel();render();break;}cancel();state.playing=true;render();toast('Playing the illustrated storyboard. No video render.');{const owner=generation;const next=()=>{if(owner!==generation||!state.playing)return;state.selected=(state.selected+1)%state.takes.length;render();timer=setTimeout(next,1500);};timer=setTimeout(next,1500);}break;
    }
  });
  document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);
    if(form.id==='reference-link-form'){try{const url=new URL(String(data.get('url')).trim());if(url.protocol!=='https:'||!['instagram.com','www.instagram.com','m.instagram.com'].includes(url.hostname)||url.username||url.password||url.port||!/^\/reels?\/[A-Za-z0-9_-]+\/?$/.test(url.pathname))throw new Error();state.reference.url='https://www.instagram.com'+url.pathname.replace(/\/?$/,'/');dirty();render();toast('Reference link saved. No video downloaded or analyzed.');}catch{toast('Paste an https Instagram reel link, such as instagram.com/reel/…');}return;}
    if(form.id==='reference-shot-form'){const shot=state.reference.shots[Number(form.dataset.index)],duration=Number(data.get('duration'));if(!Number.isInteger(duration)||duration<1||duration>30)return;for(const key of ['name','framing','angle','movement','pose','transition'])shot[key]=String(data.get(key)).trim();shot.duration=duration;shot.reviewed=false;state.reference.applied=false;dirty();$('#sheet').close();render();return;}
    if(form.id==='brief-form'){state.brief=String(data.get('brief')).trim();state.hook=String(data.get('hook')).trim();state.length=Number(data.get('length'));state.mood=String(data.get('mood'));dirty();render();toast('Objective updated. Shot edits and timings are preserved.');}
    if(form.id==='chat-form'){state.briefChatOpen=true;const text=String(data.get('message')).trim();if(!text)return;state.messages.push({role:'creator',text},{role:'director',text:'Added to your objective. Shape it into a cue in the shot plan. (Scripted reply)'});state.brief+=' '+text;dirty();render();$('.scroll-content').scrollTop=$('.scroll-content').scrollHeight;}
    if(form.id==='shot-form'){const s=state.shots[Number(form.dataset.index)];s.name=String(data.get('name')).trim();s.cue=String(data.get('cue')).trim();s.duration=Number(data.get('duration'));s.source=String(data.get('source'));dirty();$('#sheet').close();render();}
  });
  document.addEventListener('input',e=>{if(e.target.id==='project-search'){state.projectQuery=e.target.value;$('#saved-project-list').innerHTML=libraryCards();return;}if(e.target.id==='project-name'){state.projectName=e.target.value;dirty();const status=$('#save-status');if(status)status.textContent='● Unsaved changes';}});
  document.addEventListener('change',e=>{const el=e.target;
    if(el.id==='reference-file'){const f=el.files?.[0];if(!f)return;if(!f.type.startsWith('video/')){toast('Choose a video file.');el.value='';return;}state.reference.file={name:f.name.slice(0,200),size:f.size,type:f.type};dirty();render();toast('Video name and size noted. The file was not read or uploaded.');return;}
    if(el.dataset.referenceReview!==undefined){state.reference.shots[Number(el.dataset.referenceReview)].reviewed=el.checked;state.reference.applied=false;dirty();const pos=$('.scroll-content').scrollTop;render();$('.scroll-content').scrollTop=pos;return;}
    if(el.dataset.referenceOption){state.reference.options[el.dataset.referenceOption]=el.checked;state.reference.applied=false;dirty();const pos=$('.scroll-content').scrollTop;render();$('.scroll-content').scrollTop=pos;return;}
    if(el.dataset.trim){const t=state.takes[state.selected];if(!t)return;const v=Number(el.value);if(!Number.isFinite(v)||v<0||v>t.duration||(el.dataset.trim==='in'&&v>=t.out)||(el.dataset.trim==='out'&&v<=t.in)){toast('Keep the out point after the in point, within this take.');el.value=t[el.dataset.trim];return;}t[el.dataset.trim]=v;dirty();const duration=$('.timeline-clip.selected small'),summary=$('.timeline-label span:last-child');if(duration)duration.textContent=`${t.out-t.in}s`;if(summary)summary.textContent=`${editDuration()}s · 9:16`;}
    if(el.dataset.subtitle!==undefined){state.subtitles[Number(el.dataset.subtitle)]=el.value;dirty();}
    if(el.id==='music'){state.music=el.value;dirty();}
    if(el.id==='clip-angle'){state.takes[state.selected].source=el.value;dirty();const preview=$('.reel-preview .preview-label');if(preview)preview.textContent=sourceName(el.value)+' · STORYBOARD';}
  });
  window.addEventListener('hashchange',()=>{const raw=location.hash.slice(1),next=raw==='export'?'project':raw;if((views.some(v=>v[0]===next)||next==='overview')&&state.view!==next){go(next);}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){cancel();state.phase='paused';state.cue='Session paused. Start the director when you return.';if(['camera','direction'].includes(state.view))render();}});
  window.addEventListener('pagehide',cancel);
  const raw=location.hash.slice(1),initial=raw==='export'?'project':raw;if(views.some(v=>v[0]===initial)||initial==='overview')state.view=initial;
  render();
})();
